local function metrics_flag_specs()
  local specs = {}
  for _, name in ipairs(METRICS_BOOL_FLAGS) do
    specs[#specs + 1] = { name = name, bool = true }
  end
  for _, name in ipairs(METRICS_VALUE_FLAGS) do
    specs[#specs + 1] = { name = name, type = "STRING" }
  end
  return specs
end

