function M.scan_buffer(bufnr)
  if not api.nvim_buf_is_valid(bufnr) then
    return {}
  end

  local ok_p, parser = pcall(ts.get_parser, bufnr, "lua")
  if not ok_p or not parser then
    return {}
  end

  local ok_t, trees = pcall(parser.parse, parser)
  if not ok_t or not trees or #trees == 0 then
    return {}
  end

  return scan_tree(trees[1]:root(), bufnr)
end

function M.scan_source(src)
  local ok_p, parser = pcall(ts.get_string_parser, src, "lua")
  if not ok_p or not parser then
    return {}
  end

  local ok_t, trees = pcall(parser.parse, parser)
  if not ok_t or not trees or #trees == 0 then
    return {}
  end

  return scan_tree(trees[1]:root(), src)
end

function M.normalize_dir(path)
  local p = vim.fn.fnamemodify(vim.fn.expand(path), ":p")
  return (p:gsub("\\", "/"):gsub("/+$", ""))
end

function M.is_type_file(path)
  return path:match("[/\\]@types[/\\]") ~= nil or path:match("[/\\]@types%.lua$") ~= nil
end

