local function sorted_folders(state)
  local list = {}
  for folder, stats in pairs(state.folder_summary) do
    list[#list + 1] = { folder = folder, stats = stats }
  end
  sort(list, function(a, b)
    return (a.stats.total_lines or 0) > (b.stats.total_lines or 0)
  end)
  return list
end

