function M.save(dir, ns, entries)
  local index_entries = {}
  for _, e in ipairs(entries) do
    index_entries[#index_entries + 1] = {
      entry = e,
      file_mtime = get_mtime(e.filename) or os.time(),
      indexed_at = os.time(),
    }
  end

  local blob = {
    version = CACHE_VERSION,
    indexed_at = os.time(),
    cwd = vim.fn.getcwd(),
    entries = index_entries,
  }

  local path = cache_path(dir, ns)
  return require("lib.nvim.fs.json").write(path, blob)
end

function M.get(scope, force_rebuild)
  local cfg = config.get()
  scope = scope or cfg.symbols.default_scope or "cwd"

  if scope == "buffer" then
    return M.get_buffer()
  end

  -- CWD scope
  if cfg.symbols.use_treesitter_for_lua then
    return M.get_cwd_ts_lua(cfg, force_rebuild)
  end

  return rg_index.get(cfg, force_rebuild)
end

